 15	/// Error returned by [`ToonOptions::validate()`] when structural invariants are violated.
 16	#[derive(Debug, Clone, PartialEq)]
 17	#[non_exhaustive]
 18	pub enum ToonError {
 19	    /// `type_name` contains a structural character (`[`, `]`, `{`, `}`, `\n`, `\r`).
 20	    InvalidTypeName {
 21	        /// The offending name.
 22	        name: String,
 23	    },
 24	    /// A field name contains a structural character (`,`, `{`, `}`, `\n`, `\r`).
 25	    InvalidFieldName {
 26	        /// The offending field name.
 27	        name: String,
 28	    },
 29	    /// Row `row_index` has `actual` values but `fields` declares `expected`.
 30	    RowLengthMismatch {
 31	        /// Zero-based index of the mismatched row.
 32	        row_index: usize,
 33	        /// Number of fields declared in the header.
 34	        expected: usize,
 35	        /// Actual number of values in the row.
 36	        actual: usize,
 37	    },
 38	    /// An item in [`list()`] could not be rendered as a TOON row.
 39	    ///
 40	    /// Items must serialize to a JSON object (`serde_json::Value::Object`).
 41	    /// Scalars, arrays, and `null` values cannot be represented as TOON rows.
 42	    InvalidItem {
 43	        /// Zero-based index of the invalid item.
 44	        row_index: usize,
 45	        /// Reason why the item is invalid.
 46	        reason: String,
 47	    },
 48	}
 49	
 50	impl std::fmt::Display for ToonError {
 51	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 52	        match self {
 53	            Self::InvalidTypeName { name } => {
 54	                write!(f, "type_name {name:?} contains a structural character")
 55	            }
 56	            Self::InvalidFieldName { name } => {
 57	                write!(f, "field {name:?} contains a structural character")
 58	            }
 59	            Self::RowLengthMismatch { row_index, expected, actual } => {
 60	                write!(f, "row {row_index} has {actual} values but {expected} fields declared")
 61	            }
 62	            Self::InvalidItem { row_index, reason } => {
 63	                write!(f, "item at index {row_index} cannot be rendered as a TOON row: {reason}")
 64	            }
 65	        }
 66	    }
 67	}
