 71	/// Options for rendering a TOON document.
 72	#[derive(Debug, Clone)]
 73	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
 74	#[non_exhaustive]
 75	pub struct ToonOptions {
 76	    /// Snake_case type name, e.g. `"issue"`, `"component"`.
 77	    pub type_name: String,
 78	    /// Ordered field names for the header, e.g. `["number", "title", "state"]`.
 79	    pub fields: Vec<String>,
 80	    /// Rows, each a Vec of values parallel to `fields`.
 81	    pub rows: Vec<Vec<Value>>,
 82	    /// Total available count (emitted as `totalCount: N` when `Some`).
 83	    pub total_count: Option<usize>,
 84	    /// Agent-facing usage hints. Emitted as `help[N]:` block when non-empty.
 85	    pub hints: Vec<String>,
 86	    /// Max string cell length before inline truncation. Default: 200.
 87	    pub max_cell_len: usize,
 88	}
 89	
 90	impl ToonOptions {
 91	    /// Create a new ToonOptions struct with type_name and fields.
 92	    #[must_use]
 93	    pub fn new(type_name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
 94	        Self { type_name: type_name.into(), fields, rows, total_count: None, hints: Vec::new(), max_cell_len: 200 }
 95	    }
 96	
 97	    /// Set total count option.
 98	    #[must_use]
 99	    pub fn total_count(mut self, total: Option<usize>) -> Self {
100	        self.total_count = total;
101	        self
102	    }
103	
104	    /// Set hints option.
105	    #[must_use]
106	    pub fn hints(mut self, hints: Vec<String>) -> Self {
107	        self.hints = hints;
108	        self
109	    }
110	
111	    /// Set max cell length option.
112	    #[must_use]
113	    pub fn max_cell_len(mut self, len: usize) -> Self {
114	        self.max_cell_len = len;
115	        self
116	    }
117	
118	    /// Validate structural invariants and return the proof required to render.
119	    ///
120	    /// Delegates to [`ToonDocument::validate`]. Validation is mandatory:
121	    /// rendering consumes the [`ToonDocument`] this returns, so there is no
122	    /// path from an unvalidated `ToonOptions` to rendered output.
123	    ///
124	    /// # Errors
125	    ///
126	    /// Returns [`ToonError::InvalidTypeName`] if `type_name` contains a
127	    /// structural character, [`ToonError::InvalidFieldName`] if any field name
128	    /// contains a structural character, or [`ToonError::RowLengthMismatch`] if
129	    /// any row's length differs from `fields.len()`.
130	    pub fn validate(&self) -> Result<ToonDocument<'_>, ToonError> {
131	        ToonDocument::validate(self)
132	    }
133	}
