148	const _: fn(&ToonOptions) -> Result<String, ToonError> = render_toon;
149	
150	/// Render a TOON document to a string.
151	///
152	/// # Errors
153	///
154	/// Returns [`ToonError`] if `opts` fails structural validation — see
155	/// [`ToonOptions::validate`] for the exact conditions.
156	pub fn render_toon(opts: &ToonOptions) -> Result<String, ToonError> {
157	    opts.validate().map(|doc| doc.render())
158	}
