160	#[cfg(feature = "serde")]
161	fn json_value_to_toon_value(v: Option<&serde_json::Value>) -> Value {
162	    match v {
163	        None | Some(serde_json::Value::Null) => Value::Null,
164	        Some(serde_json::Value::Bool(b)) => Value::Bool(*b),
165	        Some(serde_json::Value::Number(n)) => {
166	            if let Some(i) = n.as_i64() {
167	                Value::Int(i)
168	            } else if let Some(f) = n.as_f64() {
169	                Value::Float(f)
170	            } else {
171	                Value::Str(compact_str::CompactString::new(n.to_string()))
172	            }
173	        }
174	        Some(serde_json::Value::String(s)) => Value::Str(compact_str::CompactString::new(s)),
175	        Some(other) => Value::Str(compact_str::CompactString::new(other.to_string())),
176	    }
177	}
