179	/// Build and render a TOON document from a slice of `Serialize`-able items.
180	///
181	/// Returns the rendered TOON string on success. Returns `Err` if any item
182	/// does not serialize to a JSON object (e.g. a bare integer or string slice)
183	/// — use only with homogeneous struct slices.
184	///
185	/// Requires the `serde` feature.
186	///
187	/// # Errors
188	///
189	/// Returns [`ToonError::InvalidItem`] if an item fails to serialize or does
190	/// not produce a JSON object (struct or map required). Returns
191	/// [`ToonError::InvalidTypeName`] or [`ToonError::InvalidFieldName`] if
192	/// `type_name` or a serialized field name contains a structural character
193	/// (`[`, `]`, `{`, `}`, `,`, `\n`, `\r`).
194	#[cfg(feature = "serde")]
195	pub fn list<T: serde::Serialize>(type_name: impl Into<String>, items: &[T]) -> Result<String, ToonError> {
196	    let type_name = type_name.into();
197	    let mut fields: Vec<String> = Vec::new();
198	    let mut rows: Vec<Vec<Value>> = Vec::with_capacity(items.len());
199	    for (row_index, item) in items.iter().enumerate() {
200	        let obj = match serde_json::to_value(item) {
201	            Ok(serde_json::Value::Object(map)) => map,
202	            Ok(_) => {
203	                return Err(ToonError::InvalidItem {
204	                    row_index,
205	                    reason: "item is not a JSON object (struct or map required)".into(),
206	                });
207	            }
208	            Err(e) => {
209	                return Err(ToonError::InvalidItem { row_index, reason: e.to_string() });
210	            }
211	        };
212	        if fields.is_empty() && !obj.is_empty() {
213	            fields = obj.keys().cloned().collect();
214	        }
215	        rows.push(fields.iter().map(|f| json_value_to_toon_value(obj.get(f))).collect());
216	    }
217	    let opts = ToonOptions { type_name, fields, rows, total_count: None, hints: Vec::new(), max_cell_len: 200 };
218	    Ok(opts.validate()?.render())
219	}
