221	#[cfg(test)]
222	mod ac032_public_surface_tests {
223	    #[test]
224	    fn top_level_pub_items_are_exactly_the_spec_api_surface() {
225	        let src = include_str!("lib.rs");
226	        let mut top_level_pub_names: Vec<&str> = Vec::new();
227	        for line in src.lines() {
228	            // Only unindented lines are true crate-root items -- anything
229	            // indented is inside an `impl` block (an associated function,
230	            // e.g. `ToonOptions::new`, not a separate `michi_toon::X` item).
231	            if line != line.trim_start() {
232	                continue;
233	            }
234	            if let Some(rest) = line.strip_prefix("pub use ") {
235	                // `pub use escape::{escape_value, escape_value_quoted};` and
236	                // `pub use render::Value;` -- collect every re-exported name.
237	                let list_part = rest.trim_end_matches(';');
238	                let names_part = list_part.rsplit("::").next().unwrap_or(list_part);
239	                for name in names_part.trim_start_matches('{').trim_end_matches('}').split(',') {
240	                    top_level_pub_names.push(name.trim());
241	                }
242	            } else if let Some(rest) = line.strip_prefix("pub enum ") {
243	                top_level_pub_names.push(rest.split([' ', '{']).next().unwrap_or(rest));
244	            } else if let Some(rest) = line.strip_prefix("pub struct ") {
245	                top_level_pub_names.push(rest.split([' ', '{']).next().unwrap_or(rest));
246	            } else if let Some(rest) = line.strip_prefix("pub fn ") {
247	                top_level_pub_names.push(rest.split(['(', '<']).next().unwrap_or(rest));
248	            }
249	        }
250	        let mut expected = vec![
251	            "escape_value",
252	            "escape_value_quoted",
253	            "Value",
254	            "ToonError",
255	            "ToonOptions",
256	            "ToonDocument",
257	            "render_toon",
258	        ];
259	        if cfg!(feature = "serde") {
260	            expected.push("list");
261	        }
262	        top_level_pub_names.sort_unstable();
263	        expected.sort_unstable();
264	        assert_eq!(
265	            top_level_pub_names, expected,
266	            "top-level pub surface of lib.rs must be exactly the spec's api_surface list"
267	        );
268	    }
269	
270	    #[test]
271	    fn must_use_and_list_signature_match_the_spec() {
272	        let src = include_str!("lib.rs");
273	        assert!(
274	            src.contains("#[must_use]\n    pub fn new("),
275	            "ToonOptions::new must carry #[must_use] per api_surface"
276	        );
277	        assert!(
278	            src.contains("pub fn render_toon(opts: &ToonOptions) -> Result<String, ToonError>"),
279	            "render_toon must be the fallible signature per api_surface, with no #[must_use] (Result is already must_use)"
280	        );
281	        assert!(
282	            src.contains("pub fn list<T: serde::Serialize>(type_name: impl Into<String>, items: &[T])"),
283	            "list's first parameter must be impl Into<String>, not &str, per api_surface"
284	        );
285	    }
286	}
