  1	/// Escape a scalar value for TOON row output.
  2	pub fn escape_value(v: &str) -> std::borrow::Cow<'_, str> {
  3	    if v.is_empty() {
  4	        return std::borrow::Cow::Borrowed(v);
  5	    }
  6	
  7	    let mut needs_quote = false;
  8	    let mut quote_count = 0usize;
  9	    let mut stripped_count = 0usize;
 10	    for ch in v.chars() {
 11	        match ch {
 12	            ',' => needs_quote = true,
 13	            '"' => {
 14	                needs_quote = true;
 15	                quote_count += 1;
 16	            }
 17	            '\n' | '\r' => stripped_count += 1,
 18	            _ => {}
 19	        }
 20	    }
 21	
 22	    if !needs_quote && stripped_count == 0 {
 23	        return std::borrow::Cow::Borrowed(v);
 24	    }
 25	
 26	    let capacity = v.len() - stripped_count + quote_count + if needs_quote { 2 } else { 0 };
 27	    let mut out = String::with_capacity(capacity);
 28	    if needs_quote {
 29	        out.push('"');
 30	    }
 31	    for ch in v.chars() {
 32	        match ch {
 33	            '\n' | '\r' => {}
 34	            '"' => {
 35	                out.push('\\');
 36	                out.push(ch);
 37	            }
 38	            _ => out.push(ch),
 39	        }
 40	    }
 41	    if needs_quote {
 42	        out.push('"');
 43	    }
 44	    std::borrow::Cow::Owned(out)
 45	}
 46	
 47	/// Escape a value for TOON row output and unconditionally wrap it in quotes.
 48	pub fn escape_value_quoted(v: &str) -> String {
 49	    let mut out = String::with_capacity(v.len() + 2);
 50	    out.push('"');
 51	    for ch in v.chars() {
 52	        match ch {
 53	            '\n' | '\r' => {}
 54	            '"' => {
 55	                out.push('\\');
 56	                out.push(ch);
 57	            }
 58	            _ => out.push(ch),
 59	        }
 60	    }
 61	    out.push('"');
 62	    out
 63	}
