 65	/// Characters that are structurally significant in TOON header positions and
 66	/// must not appear verbatim in type names, field names, or hints.
 67	///
 68	/// Shared with [`ToonOptions::validate()`] to keep the two in sync.
 69	pub(crate) const STRUCTURAL: &[char] = &['[', ']', '{', '}', ',', '\n', '\r'];
 70	
 71	/// Sanitize a TOON header token (type_name or field name) for safe embedding.
 72	///
 73	/// Replaces `\n`, `\r`, and structural characters (`[`, `]`, `{`, `}`, `,`)
 74	/// with `_`. Header positions have no escaping syntax in the TOON grammar —
 75	/// replacement is the only safe option that keeps output parseable.
 76	#[must_use]
 77	pub(crate) fn sanitize_header_token(s: &str) -> std::borrow::Cow<'_, str> {
 78	    if s.chars().any(|c| STRUCTURAL.contains(&c)) {
 79	        std::borrow::Cow::Owned(s.chars().map(|c| if STRUCTURAL.contains(&c) { '_' } else { c }).collect())
 80	    } else {
 81	        std::borrow::Cow::Borrowed(s)
 82	    }
 83	}
