128	/// -- so the invariant "only `validate` can produce one" is enforced by
129	/// Rust's own field-privacy rule, not by scanning source text for known
130	/// bypass shapes. `opts` is visible only inside this module and its
131	/// descendants; since this module declares no descendants and nothing
132	/// besides `validate`/`render`, no code anywhere else in this crate --
133	/// regardless of what shape it takes (a free function, a second impl
134	/// block, a `From`/`TryFrom` impl, a type alias, or a module gated behind
135	/// an unanticipated `#[cfg(...)]`) -- can write the struct-literal
136	/// `ToonDocument { opts }` and have it compile. This module is `mod`, not
137	/// `pub`, so external code cannot even name `render::proof::ToonDocument`
138	/// directly; the type is reachable only through the `pub use` re-export
139	/// below.
140	///
141	/// This guarantee holds only GIVEN two preconditions that Rust's type
142	/// system does not itself enforce, and that are each pinned by a
143	/// dedicated assertion in `sole_constructor_for_toon_document` rather than
144	/// left as a precondition nothing verifies: (1) `opts` stays genuinely
145	/// bare-private -- widening its visibility to reach the rest of this
146	/// module is a one-token, entirely ordinary-looking edit that would grant
147	/// field access to all of `render.rs` and let a constructor live outside
148	/// `proof` entirely, defeating the guarantee above while every OTHER
149	/// check here stays green; and (2) `proof`'s true extent is what the
150	/// scanning code believes it is -- found, historically, to be defeatable
151	/// by a multi-line string literal (e.g. inside a `#[doc = "..."]`
152	/// attribute) containing a bare `}`, which an earlier, purely line-based
153	/// brace-matcher mistook for the module's real close. `find_closing_line`
154	/// now tracks actual lexical structure (string and char literals,
155	/// comments) rather than taking for granted that a closing brace is
156	/// always alone on its rustfmt-normalized line, closing that specific
157	/// hole; a companion assertion additionally pins the literal line
158	/// immediately following `proof`'s close, as
159	/// defense in depth against a future defect in that scan.
160	///
161	/// **Known, accepted residual:** none of the above closes a bypass hidden
162	/// behind `macro_rules!` expansion -- a `some_macro!();` item-position
163	/// invocation inside this module's own `impl` block is, after expansion,
164	/// code that genuinely lives inside `proof` and therefore has real field
165	/// access, the same way `validate` does. No text scan can see through
166	/// macro expansion (`include_str!`, which every guard test here reads
167	/// from, captures source as written, before expansion), so this is a
168	/// limit of the mechanism, not a missed pattern. Per this invariant's own
169	/// design record, the property being enforced is that a maintainer
170	/// *following this codebase's patterns* cannot reintroduce the defect by
171	/// accident; a maintainer deliberately writing macro-hidden field access
172	/// to evade this exact module boundary is choosing to defeat it, not
173	/// accidentally tripping over it, and is outside what a source-level
174	/// guard can mechanically prevent. Closing that residual for real would
175	/// mean asserting over post-expansion, cfg-resolved output (e.g. via
176	/// `cargo-expand`) rather than unexpanded source text -- a deliberate
177	/// scope decision, not an oversight.
178	mod proof {
179	    /// Proof that a `ToonOptions` value has passed structural validation.
180	    ///
181	    /// The only function that produces a `ToonDocument` is
182	    /// [`ToonDocument::validate`] -- see this module's own doc comment for
183	    /// why no other function anywhere in the crate can construct one.
184	    /// Borrows `&'a ToonOptions` immutably, so the validated options cannot
185	    /// be mutated while the proof is live.
186	    #[derive(Debug)]
187	    pub struct ToonDocument<'a> {
188	        opts: &'a crate::ToonOptions,
189	    }
190	
191	    impl<'a> ToonDocument<'a> {
192	        /// Validate `opts` and return a proof it satisfies every structural
193	        /// invariant [`ToonDocument::render`] depends on.
194	        ///
195	        /// # Errors
196	        ///
197	        /// Returns [`crate::ToonError::InvalidTypeName`] if `type_name` contains a
198	        /// structural character, [`crate::ToonError::InvalidFieldName`] if any
199	        /// field name contains a structural character, or
200	        /// [`crate::ToonError::RowLengthMismatch`] if any row's length differs
201	        /// from `fields.len()`.
202	        pub fn validate(opts: &'a crate::ToonOptions) -> Result<Self, crate::ToonError> {
203	            if opts.type_name.chars().any(|c| super::STRUCTURAL.contains(&c)) {
204	                return Err(crate::ToonError::InvalidTypeName { name: opts.type_name.clone() });
205	            }
206	            for field in &opts.fields {
207	                if field.chars().any(|c| super::STRUCTURAL.contains(&c)) {
208	                    return Err(crate::ToonError::InvalidFieldName { name: field.clone() });
209	                }
210	            }
211	            for (i, row) in opts.rows.iter().enumerate() {
212	                if row.len() != opts.fields.len() {
213	                    return Err(crate::ToonError::RowLengthMismatch {
214	                        row_index: i,
215	                        expected: opts.fields.len(),
216	                        actual: row.len(),
217	                    });
218	                }
219	            }
220	            Ok(Self { opts })
221	        }
222	
223	        /// Render `self` to a TOON document string. Infallible and total by
224	        /// construction: `self.opts`'s row arity was already proven equal to
225	        /// `self.opts.fields.len()` by `validate`, so this iterates rows and
226	        /// fields in lockstep instead of indexing by position, which could fail.
227	        #[must_use]
228	        pub fn render(&self) -> String {
229	            use std::fmt::Write as _;
230	
231	            let opts = self.opts;
232	            let row_count = opts.rows.len();
233	            let field_count = opts.fields.len();
234	            let capacity = 60 + row_count * (field_count * 12 + 10) + opts.hints.len() * 60;
235	            let mut out = String::with_capacity(capacity);
236	
237	            out.push_str(&super::sanitize_header_token(&opts.type_name));
238	            out.push('[');
239	            out.push_str(&row_count.to_string());
240	            out.push_str("]{");
241	            for (i, field) in opts.fields.iter().enumerate() {
242	                if i > 0 {
243	                    out.push(',');
244	                }
245	                out.push_str(&super::sanitize_header_token(field));
246	            }
247	            out.push_str("}:\n");
248	
249	            for row in &opts.rows {
250	                out.push_str("  ");
251	                for (i, cell) in row.iter().enumerate() {
252	                    if i > 0 {
253	                        out.push(',');
254	                    }
255	                    match cell {
256	                        super::Value::Str(s) => {
257	                            if s.len() <= opts.max_cell_len {
258	                                out.push_str(&super::escape_value(s));
259	                            } else {
260	                                let truncated = michi_truncate::truncate_inline(s, opts.max_cell_len, "full=true");
261	                                out.push_str(&super::escape_value(&truncated));
262	                            }
263	                        }
264	                        super::Value::Int(n) => {
265	                            let _ = write!(out, "{n}");
266	                        }
267	                        super::Value::Float(f) => {
268	                            if f.is_nan() || f.is_infinite() {
269	                                let s = f.to_string();
270	                                let _ = write!(out, "\"{s}\"");
271	                            } else {
272	                                let _ = write!(out, "{f}");
273	                            }
274	                        }
275	                        super::Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
276	                        super::Value::Null => {}
277	                    }
278	                }
279	                out.push('\n');
280	            }
281	
282	            if let Some(total) = opts.total_count {
283	                out.push_str("totalCount: ");
284	                out.push_str(&total.to_string());
285	                out.push('\n');
286	            }
287	
288	            if !opts.hints.is_empty() {
289	                out.push_str("help[");
290	                out.push_str(&opts.hints.len().to_string());
291	                out.push_str("]:\n");
292	                for hint in &opts.hints {
293	                    out.push_str("  ");
294	                    out.push_str(&super::sanitize_hint(hint));
295	                    out.push('\n');
296	                }
297	            }
298	
299	            out
300	        }
301	    }
302	}
