606	/// Text-based scanning helpers shared by this crate's structural guard
607	/// tests. `pub(crate)` (not private) so both `render`'s own guard tests
608	/// and `lib.rs`'s (e.g. the AC-013 docs guard) can reuse the same,
609	/// independently-hardened implementation instead of each maintaining its
610	/// own copy that can drift out of sync or regress individually.
611	#[cfg(test)]
612	pub(crate) mod test_scan {
613	    /// Finds the byte offset, within `src`, of the `{` that opens
614	    /// `lines[open_line_idx]`'s block -- the first `{` on or after that
615	    /// line's start.
616	    fn brace_byte_offset(lines: &[&str], open_line_idx: usize) -> usize {
617	        let line_start: usize = lines[..open_line_idx].iter().map(|l| l.len() + 1).sum();
618	        line_start + lines[open_line_idx].find('{').expect("opening line must contain '{'")
619	    }
620	
621	    /// Finds the real nesting depth's matching `}` for the `{` at
622	    /// `open_brace_idx` in `src`, and returns the index of the LINE
623	    /// containing that `}` (via a byte-offset -> line-index scan over
624	    /// `lines`).
625	    ///
626	    /// Tracks actual lexical structure -- string literals (including ones
627	    /// that span multiple lines, e.g. inside a `#[doc = "..."]` value),
628	    /// raw strings with any number of `#`s, char literals (including
629	    /// `'\u{XXXX}'` escapes), and `//`/`/* */` comments -- rather than
630	    /// assuming a block's closing brace is always alone on its own
631	    /// rustfmt-normalized line. That assumption is false: rustfmt does not
632	    /// reformat the CONTENTS of a string literal, so a multi-line string
633	    /// (a pasted JSON/TOON example inside a doc comment, for instance)
634	    /// containing a bare `}` at column 0 previously fooled the
635	    /// line-alone-ness check into treating it as the block's real close,
636	    /// silently truncating everything scanned after it -- proven by
637	    /// exit-gate review, which used exactly that shape to hide a second
638	    /// constructor inside what this scan believed was `proof`'s full body.
639	    pub(crate) fn find_closing_line(src: &str, lines: &[&str], open_line_idx: usize, indent: usize) -> usize {
640	        let _ = indent; // kept in the signature for call-site stability; no longer load-bearing
641	        let open_brace_idx = brace_byte_offset(lines, open_line_idx);
642	
643	        #[derive(Clone, Copy, PartialEq)]
644	        enum State {
645	            Normal,
646	            InString,
647	            InRawString(usize),
648	            InLineComment,
649	            InBlockComment,
650	        }
651	
652	        let chars: Vec<char> = src[open_brace_idx..].char_indices().map(|(_, c)| c).collect();
653	        let byte_of: Vec<usize> = src[open_brace_idx..].char_indices().map(|(i, _)| i).collect();
654	        let mut state = State::Normal;
655	        let mut depth = 0i32;
656	        let mut i = 0usize;
657	        while i < chars.len() {
658	            let c = chars[i];
659	            match state {
660	                State::Normal => {
661	                    if c == '"' {
662	                        state = State::InString;
663	                        i += 1;
664	                    } else if c == 'r' && matches!(chars.get(i + 1), Some('"') | Some('#')) {
665	                        let mut hashes = 0usize;
666	                        let mut j = i + 1;
667	                        while chars.get(j) == Some(&'#') {
668	                            hashes += 1;
669	                            j += 1;
670	                        }
671	                        if chars.get(j) == Some(&'"') {
672	                            state = State::InRawString(hashes);
673	                            i = j + 1;
674	                        } else {
675	                            i += 1;
676	                        }
677	                    } else if c == '\'' {
678	                        // A char literal, not a lifetime, only if a closing
679	                        // `'` is found either 2 chars later (plain, e.g.
680	                        // '{') or after a `\...` escape (e.g. '\\', '\'',
681	                        // '\u{XXXX}'). A lifetime ('a, 'static) never has a
682	                        // `'` two-or-few characters later in valid syntax.
683	                        if chars.get(i + 1) == Some(&'\\') {
684	                            if chars.get(i + 2) == Some(&'u') && chars.get(i + 3) == Some(&'{') {
685	                                let close = (i + 4..chars.len())
686	                                    .find(|&k| chars[k] == '}')
687	                                    .expect("unclosed \\u{ escape in char literal");
688	                                i = close + 2; // skip past '}' and the closing '
689	                            } else {
690	                                i += 4; // ' \ x '
691	                            }
692	                        } else if chars.get(i + 2) == Some(&'\'') {
693	                            i += 3; // ' x '
694	                        } else {
695	                            i += 1; // a lifetime; not a char literal
696	                        }
697	                    } else if c == '/' && chars.get(i + 1) == Some(&'/') {
698	                        state = State::InLineComment;
699	                        i += 2;
700	                    } else if c == '/' && chars.get(i + 1) == Some(&'*') {
701	                        state = State::InBlockComment;
702	                        i += 2;
703	                    } else if c == '{' {
704	                        depth += 1;
705	                        i += 1;
706	                    } else if c == '}' {
707	                        depth -= 1;
708	                        if depth == 0 {
709	                            let close_byte = open_brace_idx + byte_of[i];
710	                            return src[..close_byte].matches('\n').count();
711	                        }
712	                        i += 1;
713	                    } else {
714	                        i += 1;
715	                    }
716	                }
717	                State::InString => {
718	                    if c == '\\' {
719	                        i += 2;
720	                    } else if c == '"' {
721	                        state = State::Normal;
722	                        i += 1;
723	                    } else {
724	                        i += 1;
725	                    }
726	                }
727	                State::InRawString(hashes) => {
728	                    if c == '"' && (1..=hashes).all(|k| chars.get(i + k) == Some(&'#')) {
729	                        state = State::Normal;
730	                        i += 1 + hashes;
731	                    } else {
732	                        i += 1;
733	                    }
734	                }
735	                State::InLineComment => {
736	                    if c == '\n' {
737	                        state = State::Normal;
738	                    }
739	                    i += 1;
740	                }
741	                State::InBlockComment => {
742	                    if c == '*' && chars.get(i + 1) == Some(&'/') {
743	                        state = State::Normal;
744	                        i += 2;
745	                    } else {
746	                        i += 1;
747	                    }
748	                }
749	            }
750	        }
751	        panic!("no matching closing brace found for the block opened at line {open_line_idx}");
752	    }
753	
754	    pub(crate) fn indent_of(line: &str) -> usize {
755	        line.len() - line.trim_start().len()
756	    }
757	
758	    /// Strips every `#[cfg(test)]`/`#[cfg(all(test, ...))]`-gated
759	    /// `mod ... { ... }` block from `src`, not via a first-occurrence
760	    /// prefix split -- a prefix split silently stops scanning at the first
761	    /// test module even if real (non-test) code follows it later in the
762	    /// file.
763	    ///
764	    /// `is_test_cfg_attr` requires `test` as the leading, positive conjunct
765	    /// of an `all(...)` -- `#[cfg(all(test, ...))]` -- rather than merely
766	    /// checking whether the attribute's text contains the substring
767	    /// `"test"` anywhere. A substring check is a real, previously-shipped
768	    /// bug: `#[cfg(all(not(test), ...))]` also contains `"test"`, so it
769	    /// would be misclassified as test-only and stripped from this scan,
770	    /// even though rustc compiles it into every *non*-test build -- the
771	    /// opposite of test-only. Any other `#[cfg(` line whose text contains
772	    /// `"test"` and isn't one of the two recognized positive forms trips
773	    /// the assertion below instead of being silently mishandled in either
774	    /// direction.
775	    pub(crate) fn strip_test_modules(src: &str) -> String {
776	        fn is_recognized_test_cfg_attr(trimmed: &str) -> bool {
777	            trimmed == "#[cfg(test)]"
778	                || trimmed.starts_with("#[cfg(all(test,")
779	                || trimmed.starts_with("#[cfg(all(test)")
780	        }
781	
782	        let lines: Vec<&str> = src.lines().collect();
783	        let mut kept: Vec<&str> = Vec::with_capacity(lines.len());
784	        let mut i = 0usize;
785	        while i < lines.len() {
786	            let trimmed = lines[i].trim_start();
787	            if trimmed.starts_with("#[cfg(") && trimmed.contains("test") {
788	                assert!(
789	                    is_recognized_test_cfg_attr(trimmed),
790	                    "unrecognized cfg attribute mentioning \"test\": {trimmed:?} -- add it to \
791	                     is_recognized_test_cfg_attr only if it is genuinely test-only; a `not(test)` \
792	                     predicate must NOT be treated as test-only"
793	                );
794	                let mod_line = i + 1;
795	                assert!(
796	                    lines[mod_line].trim_start().contains("mod ") && lines[mod_line].ends_with('{'),
797	                    "expected a `[pub(...)] mod ... {{` line immediately after a test cfg attribute, got: {:?}",
798	                    lines[mod_line]
799	                );
800	                let close = find_closing_line(src, &lines, mod_line, indent_of(lines[i]));
801	                i = close + 1;
802	            } else {
803	                kept.push(lines[i]);
804	                i += 1;
805	            }
806	        }
807	        kept.join("\n")
808	    }
809	}
