815	    #[test]
816	    fn sole_constructor_for_toon_document() {
817	        // ToonDocument's private field is declared inside `mod proof`, a
818	        // module containing nothing else. Rust's own field-privacy rule --
819	        // visible only to the declaring module and its descendants -- is
820	        // what actually prevents every bypass shape three rounds of
821	        // adversarial review found (a free fn, a second impl block, a
822	        // From/TryFrom impl, a type alias, and a module gated behind an
823	        // unanticipated #[cfg(...)]): none of them can compile unless
824	        // they're written inside `proof` itself, regardless of what shape
825	        // they take. That guarantee doesn't need a text scan; rustc enforces
826	        // it the moment anyone tries. What a text scan still needs to pin
827	        // down is the two things privacy alone doesn't cover: that `proof`
828	        // stays exactly as narrow as this reasoning requires (nothing else
829	        // declared inside it, no descendant module of its own), and that no
830	        // extra method sneaks into ToonDocument's own impl block from
831	        // within its rightful scope (proven possible in round 3: a
832	        // `pub fn rebind(&self, opts) -> ToonDocument` inside the impl
833	        // block itself evaded a fn count that filtered out every
834	        // self-taking method).
835	        //
836	        // This test cannot see through macro_rules! expansion -- an item-
837	        // position macro invocation inside proof's impl block expands to
838	        // real code with real field access, but include_str! (which this
839	        // test and strip_test_modules both read from) captures source
840	        // exactly as written, before expansion. See `proof`'s own doc
841	        // comment for why this is an accepted, documented scope boundary
842	        // rather than a gap this test is meant to close.
843	        let render_src = strip_test_modules(include_str!("render.rs"));
844	
845	        let lines: Vec<&str> = render_src.lines().collect();
846	        let mod_line = lines
847	            .iter()
848	            .position(|l| l.trim_end() == "mod proof {")
849	            .expect("ToonDocument must live in a private (non-pub) `mod proof` in render.rs");
850	        let close = find_closing_line(&render_src, &lines, mod_line, indent_of(lines[mod_line]));
851	        let proof_body = lines[mod_line + 1..close].join("\n");
852	
853	        assert_eq!(
854	            proof_body.matches("mod ").count(),
855	            0,
856	            "proof must declare no descendant module -- a descendant would inherit access to the private field"
857	        );
858	        // Exactly two fns may exist anywhere in `proof`: validate and
859	        // render. This is a total count over every `fn`, with no
860	        // self-receiver exemption -- the exemption is exactly what let
861	        // `rebind` (a &self method) through in round 3.
862	        let fn_names: Vec<&str> =
863	            proof_body.split("fn ").skip(1).map(|rest| rest.split(['(', '<']).next().unwrap_or(rest).trim()).collect();
864	        assert_eq!(
865	            fn_names,
866	            vec!["validate", "render"],
867	            "proof's impl block must contain exactly these two fns, in this order; found: {fn_names:?}"
868	        );
869	        // fn_names only sees items introduced by the literal token `fn `.
870	        // A `const`/`static` item, or a function-pointer-typed const
871	        // (`fn(...)  ->  ToonDocument`, no space before the paren) can
872	        // produce a ToonDocument without ever containing that token --
873	        // proven by exit-gate review: `pub const MAKE: for<'x> fn(&'x
874	        // ToonOptions) -> ToonDocument<'x> = |o| ToonDocument { opts: o };`
875	        // compiled, passed every check above, and rendered unvalidated
876	        // data through a crate-internal caller.
877	        for banned in ["const ", "static ", "fn("] {
878	            assert_eq!(
879	                proof_body.matches(banned).count(),
880	                0,
881	                "proof may declare no {banned:?} item -- a const/static/fn-pointer can produce \
882	                 a ToonDocument without ever introducing a `fn ` token for the fn-name check above to see"
883	            );
884	        }
885	
886	        // Module privacy only closes external bypass shapes AS LONG AS the
887	        // field itself stays bare-private (no `pub`/`pub(in ...)`/
888	        // `pub(crate)` etc.) -- widening it to `pub(in crate::render)` is a
889	        // one-token edit that grants field access to all of render.rs,
890	        // letting a constructor live entirely outside proof while every
891	        // other assertion here stays green (proven by exit-gate review).
892	        assert!(
893	            proof_body.contains("\n        opts: &'a crate::ToonOptions,\n"),
894	            "ToonDocument's field must stay bare-private (no visibility modifier); \
895	             found a different declaration in proof_body: {proof_body:?}"
896	        );
897	        assert_eq!(
898	            render_src.matches("pub(in ").count(),
899	            0,
900	            "no item in render.rs may use a `pub(in ...)` visibility -- it can widen field access \
901	             beyond proof without tripping any other check here"
902	        );
903	
904	        assert!(
905	            render_src.contains("\npub use proof::ToonDocument;"),
906	            "ToonDocument must be re-exported from proof via `pub use`, not by widening proof's own visibility"
907	        );
908	        // Defense in depth: pin what immediately follows proof's own
909	        // closing brace, so even an unanticipated future defect in the
910	        // string/comment-aware scan above that find_closing_line performs
911	        // fails loudly here instead of silently accepting a truncated or
912	        // extended proof_body.
913	        assert_eq!(
914	            lines[close + 1],
915	            "pub use proof::ToonDocument;",
916	            "the line immediately after proof's closing brace must be its pub use re-export"
917	        );
918	
919	        let lib_src = strip_test_modules(include_str!("lib.rs"));
920	        let escape_src = strip_test_modules(include_str!("escape.rs"));
921	        for (file, src) in
922	            [("render.rs", render_src.as_str()), ("lib.rs", lib_src.as_str()), ("escape.rs", escape_src.as_str())]
923	        {
924	            let scan = src.to_lowercase().replace("unsafe_code", "");
925	            for bad in ["unchecked", "unsafe", "raw", "assume"] {
926	                assert!(!scan.contains(bad), "escape-hatch name pattern {bad:?} must not appear in {file}");
927	            }
928	        }
929	    }
