                    }
                    match cell {
                        super::Value::Str(s) => {
                            if s.len() <= opts.max_cell_len {
                                out.push_str(&super::escape_value(s));
                            } else {
                                let truncated = michi_truncate::truncate_inline(s, opts.max_cell_len, "full=true");
                                out.push_str(&super::escape_value(&truncated));
                            }
                        }
                        super::Value::Int(n) => {
