  7	/// Cell strategy mixing plain alphanumeric text with strings drawn from a
  8	/// charset that includes comma, double-quote, and newline/CR — the exact
  9	/// characters `escape_value` treats specially — so the round-trip test
 10	/// regularly exercises quoting/escaping, not just the happy path.
 11	fn cell_strategy() -> impl Strategy<Value = String> {
 12	    let escaping_char = prop_oneof![
 13	        Just(','),
 14	        Just('"'),
 15	        Just('\n'),
 16	        Just('\r'),
 17	        proptest::char::range('a', 'z'),
 18	        proptest::char::range('0', '9'),
 19	    ];
 20	    prop_oneof![
 21	        "[a-zA-Z0-9 ]{0,20}",
 22	        proptest::collection::vec(escaping_char, 0..20).prop_map(|chars| chars.into_iter().collect()),
 23	    ]
 24	}
 25	
 26	/// Row/field counts and the `total_count` option are generated first, then
 27	/// the cell grid is generated depending on them (`field_count` columns ×
 28	/// `row_count` rows) via `prop_flat_map` — the `proptest!` macro's `x in
 29	/// strategy` bindings can't reference each other directly, so the dependent
 30	/// composition has to happen outside it.
 31	fn doc_strategy() -> impl Strategy<Value = (String, usize, usize, Option<usize>, Vec<Vec<String>>)> {
 32	    ("[a-z][a-z0-9_]{0,10}", 1usize..4, 0usize..5, proptest::option::of(0usize..10_000)).prop_flat_map(
 33	        |(type_name, field_count, row_count, total_count)| {
 34	            proptest::collection::vec(proptest::collection::vec(cell_strategy(), field_count), row_count)
 35	                .prop_map(move |cells| (type_name.clone(), field_count, row_count, total_count, cells))
 36	        },
 37	    )
 38	}
 39	
 40	proptest! {
 41	    #[test]
 42	    fn render_toon_output_is_grammar_valid(
 43	        (type_name, field_count, row_count, total_count, cells) in doc_strategy(),
 44	    ) {
 45	        let fields: Vec<String> = (0..field_count).map(|i| format!("f{i}")).collect();
 46	        // Each cell is generated independently per row×field position (rather
 47	        // than reusing one shared value everywhere), so a bug that
 48	        // transposed rows or misaligned columns would actually be caught by
 49	        // the per-position comparison below.
 50	        let rows: Vec<Vec<Value>> =
 51	            cells.iter().map(|row| row.iter().map(|c| Value::Str(c.clone().into())).collect()).collect();
 52	        let opts = ToonOptions::new(type_name.clone(), fields.clone(), rows.clone()).total_count(total_count);
 53	        let rendered = render_toon(&opts).expect("doc_strategy only generates arity-matched, structural-char-free options");
 54	
 55	        let parsed = parse(&rendered).expect("render_toon output must be parseable by the grammar");
 56	        prop_assert_eq!(parsed.type_name, type_name);
 57	        prop_assert_eq!(parsed.fields, fields);
 58	        prop_assert_eq!(parsed.rows.len(), row_count);
 59	        prop_assert_eq!(parsed.total_count, total_count);
 60	        for (parsed_row, original_row) in parsed.rows.iter().zip(rows.iter()) {
 61	            for (parsed_cell, original_value) in parsed_row.iter().zip(original_row.iter()) {
 62	                // escape_value strips embedded \n/\r rather than preserving
 63	                // them (TOON has no multi-line cell syntax), so the expected
 64	                // value must be normalized the same way before comparing.
 65	                let expected = value_to_string(original_value).replace(['\n', '\r'], "");
 66	                prop_assert_eq!(parsed_cell, &expected);
 67	            }
 68	        }
 69	    }
 70	}
