 89	fn mismatched_doc_strategy() -> impl Strategy<Value = (String, Vec<String>, Vec<Vec<String>>)> {
 90	    let name_strategy = prop_oneof!["[a-z][a-z0-9_]{0,10}", "[a-z]\\[[a-z]{0,5}"];
 91	    (name_strategy.clone(), proptest::collection::vec(name_strategy, 1usize..3)).prop_flat_map(|(type_name, fields)| {
 92	        let field_count = fields.len();
 93	        proptest::collection::vec(proptest::collection::vec(cell_strategy(), 0usize..field_count + 2), 0usize..4)
 94	            .prop_map(move |rows| (type_name.clone(), fields.clone(), rows))
 95	    })
 96	}
