103	        let structural = [',', '[', ']', '{', '}', '\n', '\r'];
104	        let type_name_ok = !type_name.chars().any(|c| structural.contains(&c));
105	        let fields_ok = fields.iter().all(|f| !f.chars().any(|c| structural.contains(&c)));
106	        let rows_ok = rows.iter().all(|r| r.len() == fields.len());
