49	    let mut out = String::with_capacity(v.len() + 2);
50	    out.push('"');
51	    for ch in v.chars() {
52	        match ch {
53	            '\n' | '\r' => {}
54	            '"' => {
55	                out.push('\\');
56	                out.push(ch);
57	            }
58	            _ => out.push(ch),
59	        }
60	    }
61	    out.push('"');
